TFA = "چرا حسابرسان سکوت می‌کنند؟ فشار زمانی، رفع تعهد اخلاقی و نقش وجدان حرفه‌ای"; TEN = "Why Do Auditors Stay Silent? Time-Budget Pressure, Moral Disengagement and the Role of Professional Conscience"
f = Doc(body_pt=12, body_font="B Nazanin", title_font="B Titr"); f.title(TFA); f.para("چکیدهٔ گسترده", jc="center", indent=False, bold=True, size=26, after=100)
def sec(t, body): f.para(f"**{t}**", jc="right", indent=False, size=26, before=100, after=30, keep=True); f.para(body, jc="both", indent=True, size=24, after=40)
sec("زمینه و مسئله", "حسابرس هنگام اجرای کار گاه با ناهنجاری‌هایی روبه‌رو می‌شود که اگر مطرح نشود، می‌تواند به بی‌اعتباری گزارش بینجامد. تصمیم او میان طرح موضوع و سکوت پیش از آن‌که فنی باشد اخلاقی است. پژوهش‌های داخلی فشار بودجهٔ زمانی را با رفتارهای کاهندهٔ کیفیت حسابرسی و سکوت حسابرسان را با عوامل سازمانی مرتبط دانسته‌اند، اما سازوکار شناختی که فشار را به سکوت می‌رساند کمتر آزموده شده است.")
sec("هدف و پرسش‌ها", "هدف آزمون مدلی ساده با پنج متغیر است: فشار بودجهٔ زمانی و جو اخلاقی سازمان ← رفع تعهد اخلاقی ← سکوت دربارهٔ تخلف کشف‌شده، با تعدیل‌گری وجدان حرفه‌ای. پرسش‌ها: آیا رفع تعهد اخلاقی میانجی اثر فشار و جو بر سکوت است؟ و آیا وجدان حرفه‌ای حلقه‌های این زنجیره را تضعیف می‌کند؟")
sec("مبانی نظری", "اخلاق رفتاری، ریزش اخلاقی (محوشدن بُعد اخلاقی تصمیم در شرایط فشار) و رفع تعهد اخلاقی (توجیه اخلاقی، برچسب‌زنی تلطیف‌شده، مقایسهٔ سودمند، جابه‌جایی و پخش مسئولیت) پایهٔ نظری‌اند. جو اخلاقی سازمان دامنهٔ توجیه‌پذیر را محدود می‌کند و سکوت سازمانی (تسلیم‌شده و دفاعی) پیامد نهایی است. وجدان حرفه‌ای، به‌معنای درونی‌سازی ارزش‌های اخلاقی و حرفه‌ای مانند امانت‌داری و پاسخگویی در برابر وجدان، به‌عنوان نیروی بازدارنده فرض می‌شود. هشت فرضیه صورت‌بندی شد.")
sec("روش‌شناسی", f"پژوهش کاربردی و پیمایشی است. داده‌های {n} حسابرس با پرسشنامهٔ ۲۳ گویه‌ای (پنج سازه) گردآوری و با مدل‌سازی معادلات ساختاری مبتنی بر کوواریانس کاملاً پنهان (بدون میانگین یا مجموع گویه‌ها)، دو اثر متقابل پنهان، بوت‌استرپ {R['boot_n']:,} تکراری و مقایسهٔ پنج مدل رقیب تحلیل شد.".replace("۲۳", "۲۲"))
sec("یافته‌ها", f"مدل اندازه‌گیری برازش مطلوب داشت (CFI = {m(c['cfi'],3)}؛ RMSEA = {m(c['rmsea'],3)}؛ پایایی ترکیبی {m(min(v['cr'] for v in REL.values()))} تا {m(max(v['cr'] for v in REL.values()))}؛ بیشینهٔ HTMT = {m(R['htmt_max'])}). فشار زمانی رفع تعهد را افزایش (β = {b('MD~TBP')}) و جو اخلاقی آن را کاهش داد (β = {b('MD~ECL')}). رفع تعهد قوی‌ترین پیش‌بین سکوت بود (β = {b('SIL~MD')})؛ جو اخلاقی اثر مستقیم منفی نیز بر سکوت داشت (β = {b('SIL~ECL')}) و اثر مستقیم فشار زمانی معنادار نبود (β = {b('SIL~TBP')})؛ پس اثر فشار زمانی عمدتاً از راه توجیه‌سازی می‌گذرد. وجدان حرفه‌ای هم اثر فشار بر رفع تعهد (β = {b('MD~INTT')}) و هم اثر رفع تعهد بر سکوت (β = {b('SIL~INTM')}) را تضعیف کرد و اثر غیرمستقیم فشار زمانی بر سکوت از {m(IN['TBP_MD_SIL_low']['est'])} در وجدان پایین به {m(IN['TBP_MD_SIL_high']['est'])} در وجدان بالا رسید. مدل {m(R['r2']['SIL']*100,0)} درصد واریانس سکوت را تبیین کرد. نتایج در برآوردهای جایگزین پایدار بود؛ مدل معکوس برازشی تقریباً هم‌ارز داشت، پس جهت علّی بر نظریه استوار است.")
sec("نتیجه‌گیری و پیامدها", "سکوت حسابرس بیش از آن‌که تصمیمی آگاهانه برای پنهان‌کاری باشد، پایانهٔ زنجیرهٔ فشار، توجیه و سکوت است. زمان حفاظت‌شده برای یافته‌های غیرمعمول، آموزش شناخت سازوکارهای توجیه، رهبری اخلاقی، کانال‌های امن طرح نگرانی و تقویت ارزش‌های حرفه‌ای درونی‌شده از راهکارهای اصلی‌اند.")
sec("محدودیت‌ها", "طرح مقطعی، خوداظهاری و حساسیت موضوع، تازه‌بودن دو مقیاس و هم‌ارزی مدل معکوس. پیشنهاد می‌شود از سناریوهای آزمایشی، طرح‌های روزنوشتی یا طولی و شاخص‌های عینی استفاده شود.")
f.para("**واژه‌های کلیدی:** جو اخلاقی، حسابرسی، رفع تعهد اخلاقی، سکوت، فشار بودجهٔ زمانی، وجدان حرفه‌ای", jc="right", indent=False, size=22, before=80); f.save(os.path.join(D, "Extended_Abstract_Persian.docx"))
e = DocEN(); e.title(TEN); e.para("Extended Abstract", jc="center", indent=False, bold=True, size=26, after=100)
def es(t, body): e.para(f"**{t}**", jc="left", indent=False, before=100, after=30, keep=True); e.para(body, jc="both", indent=True, after=60)
es("Background and problem", "Auditors regularly meet irregularities that, if left unraised, can undermine the credibility of a report. The choice between raising a concern and staying silent is ethical before it is technical. Iranian studies link time-budget pressure to audit-quality-reducing behaviour and organisational silence to several organisational causes, but the cognitive mechanism that converts pressure into silence has been little tested.")
es("Objective and questions", "The study tests a parsimonious five-variable model: time-budget pressure and ethical climate → moral disengagement → silence about a detected irregularity, with professional conscience as a moderator. Does moral disengagement mediate the effects of pressure and climate on silence, and does professional conscience weaken the links of this chain?")
es("Theory", "Behavioral ethics, ethical fading and moral disengagement (moral justification, euphemistic labelling, advantageous comparison, displacement and diffusion of responsibility) provide the foundations. Ethical climate narrows what can be justified; silence (acquiescent and defensive) is the end point. Professional conscience, defined as internalised ethical and professional values such as trusteeship and accountability to one's conscience, is expected to act as a restraining force. Eight hypotheses were derived.")
es("Method", f"A survey of {n} auditors with a 22-item questionnaire (five constructs) was analysed with covariance-based SEM using fully latent variables (no item sums or means), two latent interactions, a {R['boot_n']:,}-draw bootstrap, and five competing models.")
es("Findings", f"The measurement model fitted well (CFI = {c['cfi']:.3f}; RMSEA = {c['rmsea']:.3f}; CR {min(v['cr'] for v in REL.values()):.2f}–{max(v['cr'] for v in REL.values()):.2f}; max HTMT = {R['htmt_max']:.2f}). Time pressure increased moral disengagement (β = {PA['MD~TBP']['beta']:.2f}) and ethical climate reduced it (β = {PA['MD~ECL']['beta']:.2f}). Moral disengagement was the strongest predictor of silence (β = {PA['SIL~MD']['beta']:.2f}); climate had a direct negative effect (β = {PA['SIL~ECL']['beta']:.2f}) whereas the direct effect of time pressure was not significant (β = {PA['SIL~TBP']['beta']:.2f}). Professional conscience weakened both the pressure→disengagement path (β = {PA['MD~INTT']['beta']:.2f}) and the disengagement→silence path (β = {PA['SIL~INTM']['beta']:.2f}); the indirect effect of time pressure on silence fell from {IN['TBP_MD_SIL_low']['est']:.2f} to {IN['TBP_MD_SIL_high']['est']:.2f} between low and high conscience. The model explained {R['r2']['SIL']*100:.0f}% of the variance in silence. Results were robust; a reverse-path model fitted almost equally well, so causal direction rests on theory.")
es("Conclusions and implications", "Silence is less a decision to conceal than the end of a chain of pressure and justification. Protected time for unusual findings, training that exposes justification mechanisms, ethical leadership, safe channels for raising concerns and the selection and development of internalised professional values are the main recommendations.")
es("Limitations", "Cross-sectional, self-reported data on a sensitive topic, two new scales and the equivalence of the reverse model. Experimental vignettes, diary or longitudinal designs and objective indicators are recommended.")
e.para("**Keywords:** Ethical climate; auditing; moral disengagement; silence; time-budget pressure; professional conscience", indent=False, before=80); e.save(os.path.join(D, "Extended_Abstract_English.docx"), title="Extended Abstract")
q = Doc(body_pt=12, body_font="B Nazanin", title_font="B Titr"); q.title("پرسشنامهٔ پژوهش: فشار زمانی، جو اخلاقی، رفع تعهد اخلاقی، وجدان حرفه‌ای و سکوت حسابرسان")
q.para("**راهنما:** پاسخ‌ها محرمانه و تجمیعی گزارش می‌شود و هیچ اطلاعات هویتی صاحبکار خواسته نمی‌شود. لطفاً میزان موافقت خود را با هر عبارت (۱ = کاملاً مخالف … ۵ = کاملاً موافق) مشخص کنید. عبارت‌های سکوت دربارهٔ «گرایش شما در موقعیت فرضی» است، نه اعتراف به رفتار واقعی.", indent=False)
q.heading("بخش الف) ویژگی‌های جمعیت‌شناختی"); q.table("جدول ۱. پرسش‌های جمعیت‌شناختی", ["کد", "پرسش"], list(G.DEMO), widths=[900, 8100], size=22)
q.heading("بخش ب) خلاصهٔ منشأ هر مقیاس")
q.table("جدول ۲. نوع منشأ (محقق‌ساخته یا پژوهش‌محور) و منابع", ["نماد", "سازه", "گویه", "منشأ", "منابع"], [(v["code"], v["fa"], str(len(v["items"])), v["cls"], "؛ ".join(G.CITE[k][0] + " (" + str(G.CITE[k][2]) + ")" for k in v["refs"])) for v in G.VARS], widths=[700, 1700, 600, 2000, 4000], size=20)
